          candidate: input.candidate,
          candidateCaseId: candidateCase.candidateCaseId,
          candidateFingerprint: fingerprint,
          claims: resolvedClaims,
          operation,
          outcome: 'AMBIGUOUS',
          partyIds,
          tenantId: input.tenantId,
